# Capability dependency graph: Signature Seeking Rooted in the Index
edges = {"seeking -> index-soil": "soil dependency".split(";")}
# criticality: critical
order, seen = [], set()
def visit(n):
    if n in seen:
        return
    seen.add(n)
    for d in edges.get(n, []):
        visit(d)
    order.append(n)
for n in edges:
    visit(n)
print("install/start order:", order)
print("OK - dependency graph has no cycles on the sample")

